class BowlingGame:
    def __init__(self):
        self._rolls = []
        self._frame = 1
        self._frame_pins = 0
        self._tenth_rolls = []
        self._game_over = False

    def roll(self, pins):
        if not 0 <= pins <= 10:
            raise ValueError("pins must be between 0 and 10")

        if self._game_over:
            raise ValueError("cannot roll after the game is complete")

        if self._frame < 10:
            if self._frame_pins + pins > 10:
                raise ValueError("two rolls in a frame cannot score more than 10 points")
            self._frame_pins += pins
            self._rolls.append(pins)
            if self._frame_pins == 10:
                self._frame += 1
                self._frame_pins = 0
        else:
            tenth = self._tenth_rolls
            if len(tenth) == 1 and tenth[0] < 10 and tenth[0] + pins > 10:
                raise ValueError("two rolls in a frame cannot score more than 10 points")
            if len(tenth) == 2:
                if tenth[0] == 10 and tenth[1] != 10 and tenth[1] + pins > 10:
                    raise ValueError("two rolls in a frame cannot score more than 10 points")
            tenth.append(pins)
            self._rolls.append(pins)
            if len(tenth) == 3 or (len(tenth) == 2 and tenth[0] < 10 and tenth[0] + tenth[1] < 10):
                self._game_over = True

